        "cinemaAfter": null,
        "memoryKey": null,
        "stage": null,
        "emphasis": [],
        "actor": "chris",
        "arg": "default",
        "text": "그럼 아까 떠오른 것도 얘기해 줄게. 정확한 기억은 아닐 수도 있지만.",
        "en": "그럼 아까 떠오른 것도 얘기해 줄게. 정확한 기억은 아닐 수도 있지만.",
        "when": null,
