  "prologue": [
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "진입조, 진행 상황은?"
    },
    {
      "type": "say",
      "who": "진입조｜무전",
      "actor": "radio",
      "text": "지하 3층까지 정리했습니다. 하지만... 마지막 층에서 연구원들이 저항 중입니다."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "...겨우 연구원한테 막혔다고?"
    },
    {
      "type": "say",
      "who": "진입조｜무전",
      "actor": "radio",
      "text": "실험체 하나가 계속 방해를..."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "병신 같은 놈들... 직접 내려간다. 대치 상태를 유지해."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "들었지? 경계조만 남기고 다 내려간다."
    },
    {
      "type": "say",
      "who": "보안부 대원 A",
      "actor": "soldier",
      "text": "모두 진입 준비!"
    },
    {
      "type": "say",
      "who": "경계조 A｜무전",
      "actor": "radio",
      "text": "팀장님, 현재 정문에 접근하는 차량들이 있습니다."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "뭐? 자세히 말해 봐."
    },
    {
      "type": "say",
      "who": "경계조 A｜무전",
      "actor": "radio",
      "text": "지금 검은색으로 도색된 장갑차 여러 대가..."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "시발, 아군 아니잖아! 당장 격벽 올리고 쏴!!"
    },
    {
      "type": "say",
      "who": "경계조 A｜무전",
      "actor": "radio",
      "text": " 벼... 벽이 안 올라갑니다. 인트라넷 권한이..."
    },
    {
      "type": "say",
      "who": "경계조 A｜무전",
      "actor": "radio",
      "text": "야... 저 사람, 설마... 그..."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "경계조? 경계조? 응답해라."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "...시발, 좆된 것 같은데."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "다들 준비해. 손님이 온 것 같다."
    },
    {
      "type": "say",
      "who": "보안부 3팀 팀장",
      "actor": "captain",
      "text": "...쏴, 쏴!!"
    }
  ],
